package com.rescuefarm.ui.checkout;
import com.rescuefarm.domain.model.Order;
public final class CheckoutState { public enum Status{IDLE,LOADING,SUCCESS,ERROR} private final Status status;private final Order order;private final String message;private final boolean replay;private CheckoutState(Status s,Order o,String m,boolean r){status=s;order=o;message=m;replay=r;}public static CheckoutState idle(){return new CheckoutState(Status.IDLE,null,"",false);}public static CheckoutState loading(){return new CheckoutState(Status.LOADING,null,"Đang reserve tồn kho và tạo đơn…",false);}public static CheckoutState success(Order o,boolean r){return new CheckoutState(Status.SUCCESS,o,r?"Đã nhận lại đơn cũ; không reserve lần hai.":"Checkout thành công; tồn kho đã được giữ.",r);}public static CheckoutState error(String m){return new CheckoutState(Status.ERROR,null,m,false);}public Status getStatus(){return status;}public Order getOrder(){return order;}public String getMessage(){return message;}public boolean isReplay(){return replay;} }
